from collections import deque

def bfs(adj, s):
    seen = {s}
    q = deque([s])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in sorted(adj[u], reverse=True):
            if v not in seen:
                seen.add(v)
                q.append(v)
    return order

adj = {1: [2, 3], 2: [4, 5], 3: [5, 6], 4: [7], 5: [7], 6: [7], 7: []}
